"""Real 390px Chromium design/intake/transition checks with isolated fixtures."""
import http.server,socketserver,threading,subprocess,tempfile,json,struct,zlib,time
from pathlib import Path
root=Path(__file__).resolve().parents[1]/'public'
ui='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/console/style.css"><div id="app"></div><div id="toasts"></div><script type="module">
localStorage.setItem('mosaic.console.locale','en');const storeMode=location.search.includes('store'),calls=[];let releases=[],renderCalls=0;
const image={id:'imageA',name:'用户图片',type:'image',ownerStoreId:null,shared:true},video={id:'videoA',name:'用户视频',type:'video',ownerStoreId:null,shared:true},media=[image,video,{...image,id:'storeImage',ownerStoreId:'store1',shared:false}];
const cfg={width:1080,height:1920,direction:'column',ratio:30,regions:[{mediaId:'imageA',fit:'contain'},{mediaId:'videoA',fit:'cover'}],durationSeconds:15,audioRegion:null};let designs=[{id:'hq',name:'总部共享设计',ownerStoreId:null,shared:true,revision:1,body:cfg},{id:'own',name:'门店设计',ownerStoreId:'store1',shared:false,revision:1,body:cfg}];
window.fetch=async(path,opts={})=>{const body=opts.body?JSON.parse(opts.body):{};calls.push({path,body,method:opts.method||'GET'});let value=[];if(path==='/api/session')value={csrf:'fixture',user:{role:storeMode?'store_operator':'tenant_admin',name:'用户'},tenant:{name:'Tenant'}};else if(path==='/api/overview')value={};else if(path==='/api/stores')value=[{id:'store1',name:'客户门店'}];else if(path==='/api/media')value=media;else if(path==='/api/designs'){if(opts.method==='POST'){value={...body,id:'new',revision:1};designs.push(value);}else value=designs;}else if(path.endsWith('/render')){if(++renderCalls===1)throw new Error('uncertain network');value={id:'job',status:'queued'};}else if(path.endsWith('/jobs'))value=[];else if(path.includes('/intake')){if(path.includes('imageA'))value=await new Promise(resolve=>releases.push(()=>resolve({checks:[{code:'dimensions',pass:true,value:'OLD SOURCE RESULT'}]})));else value={checks:[{code:'dimensions',pass:true,value:'CURRENT SOURCE RESULT'}]};}else if(path.startsWith('/api/retail/'))value=[];return {ok:true,json:async()=>structuredClone(value)};};
const wait=(ms=100)=>new Promise(r=>setTimeout(r,ms)),find=text=>[...document.querySelectorAll('button')].find(b=>b.textContent===text),field=label=>{const l=[...document.querySelectorAll('.dialog-body label')].find(n=>n.textContent===label);return document.getElementById(l.htmlFor);},set=(label,value)=>{const n=field(label);n.value=value;n.dispatchEvent(new Event('input',{bubbles:true}));n.dispatchEvent(new Event('change',{bubbles:true}));},nav=text=>[...document.querySelectorAll('nav button')].find(b=>b.textContent.includes(text)).click(),close=()=>document.querySelector('.dialog-backdrop:last-of-type .dialog-footer button')?.click();
await import('/console/app.js');await wait();nav('Content designer');await wait();const checks={phone:innerWidth===390};
if(storeMode){const card=[...document.querySelectorAll('.retail-grid article')].find(n=>n.querySelector('h3').textContent==='总部共享设计');card.querySelector('button').click();await wait();checks.sharedReadonly=!find('Save design')&&[...document.querySelectorAll('.designer-fields input,.designer-fields select')].every(n=>n.disabled);close();const own=[...document.querySelectorAll('.retail-grid article')].find(n=>n.querySelector('h3').textContent==='门店设计');own.querySelector('button').click();await wait();checks.ownerImmutable=field('Owner store').disabled;checks.storeNoSharing=field('Share with stores (HQ only)').disabled;close();}
else{find('Create design').click();await wait();set('Name','用户新设计');field('Share with stores (HQ only)').checked=true;field('Share with stores (HQ only)').dispatchEvent(new Event('input',{bubbles:true}));find('Swap dimensions').click();checks.swap=field('Canvas width').value==='1920'&&field('Canvas height').value==='1080';checks.ratio=document.querySelector('.designer-canvas').children[0].style.flexBasis==='30%'&&document.querySelector('.designer-canvas').children[1].style.flexBasis==='70%';find('Save design').click();await wait();const saved=calls.find(c=>c.path==='/api/designs'&&c.method==='POST');checks.saved=saved.body.name==='用户新设计'&&saved.body.body.ratio===30&&saved.body.shared===true&&saved.body.ownerStoreId===null;checks.noAutoRender=!calls.some(c=>c.path.includes('/render')||c.path.includes('/publish'));find('Render playback asset').click();await wait();checks.frozen=[...document.querySelectorAll('.designer-fields input,.designer-fields select')].every(n=>n.disabled)&&find('Swap dimensions').disabled;const before=calls.length;field('Name').value='Changed during uncertainty';find('Save design').click();await wait();checks.noUncertainSave=calls.length===before;find('Render playback asset').click();await wait();const renders=calls.filter(c=>c.path.endsWith('/render'));checks.renderIdStable=renders.length===2&&renders[0].body.requestId===renders[1].body.requestId;checks.unfrozen=!field('Name').disabled;close();
nav('Retail campaigns');await wait();find('Material intake & conversion').click();await wait();find('Check specifications').click();await wait();set('Source','videoA');releases.forEach(fn=>fn());await wait();checks.staleIntakeIgnored=!document.querySelector('.dialog-body').textContent.includes('OLD SOURCE RESULT');find('Check specifications').click();await wait();checks.currentIntake=document.querySelector('.dialog-body').textContent.includes('CURRENT SOURCE RESULT');}
checks.mobile=document.documentElement.scrollWidth<=innerWidth;document.body.append(Object.assign(document.createElement('pre'),{id:'result',hidden:true,textContent:JSON.stringify(checks)}));
</script>'''
preview='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/console/style.css"><div id="app"></div><script type="module">
import {createPreview}from'/console/preview.js';const wait=ms=>new Promise(r=>setTimeout(r,ms));const until=async(fn)=>{for(let i=0;i<100;i++){if(fn())return;await wait(40);}throw Error('Preview readiness timed out');};
const el=(tag,attrs={},...children)=>{const n=document.createElement(tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);n.append(...children);return n;};
const group={layout:{mode:'freeform',canvasWidth:256,canvasHeight:128,screens:[{id:'a',name:'A',x:0,y:0,width:128,height:128,rotation:0},{id:'b',name:'B',x:128,y:0,width:128,height:128,rotation:90}]},playback:{mediaId:'imageA',epoch:Date.now(),position:0,paused:false,transition:{type:'fade',durationMs:1000}}};
const media=[{id:'imageA',type:'image'},{id:'slowImage',type:'image'},{id:'videoA',type:'video',duration:4},{id:'videoB',type:'video',duration:4},{id:'videoC',type:'video',duration:4}];const root=createPreview({group,media,serverTime:Date.now()},{el,locale:'en'});document.querySelector('#app').append(root);const surfaces=()=>[...root.querySelectorAll('.preview-surface')],allReady=(tag,id)=>surfaces().every(s=>s.querySelector(`${tag}[src="/media/${id}"]`));await until(()=>allReady('img','imageA'));const checks={initialDecode:[...root.querySelectorAll('img')].every(n=>n.complete&&n.naturalWidth===64),geometry:root.querySelectorAll('.preview-screen')[1].style.left==='50%'&&surfaces()[1].style.width==='200%'};
async function switchTo(id,tag,label){group.playback.mediaId=id;group.playback.epoch=Date.now();await until(()=>allReady(tag,id));await wait(100);checks[label+'Overlay']=surfaces().every(s=>!!s.querySelector('canvas'));checks[label+'FrozenPixels']=surfaces().every(s=>{const c=s.querySelector('canvas');return c?.getContext('2d').getImageData(0,0,1,1).data[3]===255;});checks[label+'Progress']=surfaces().every(s=>{const alpha=Number(s.querySelector('canvas')?.style.opacity);return alpha>0&&alpha<1;});if(tag==='video')checks[label+'Decoded']=[...root.querySelectorAll('video')].every(n=>n.readyState>=2&&n.videoWidth===64&&!n.paused);await wait(1100);checks[label+'Released']=surfaces().every(s=>!s.querySelector('canvas'));}
await switchTo('videoA','video','imageVideo');group.playback.mediaId='slowImage';group.playback.epoch=Date.now();await wait(200);checks.pendingKeepsPrevious=surfaces().every(s=>s.querySelector('video[src="/media/videoA"]')?.readyState>=2);await until(()=>allReady('img','slowImage'));checks.videoImageFrozen=surfaces().every(s=>!!s.querySelector('canvas'));await wait(1100);await switchTo('videoB','video','imageVideo2');await switchTo('videoC','video','videoVideo');const nodes=[...root.querySelectorAll('video')];root.remove();await wait(200);checks.teardown=nodes.every(n=>n.paused&&!n.hasAttribute('src'));checks.phone=innerWidth===390;checks.mobile=document.documentElement.scrollWidth<=innerWidth;document.body.append(Object.assign(document.createElement('pre'),{id:'result',hidden:true,textContent:JSON.stringify(checks)}));
</script>'''
def png(color):
 chunk=lambda t,d:struct.pack('!I',len(d))+t+d+struct.pack('!I',zlib.crc32(t+d)&0xffffffff)
 return b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('!2I5B',64,32,8,2,0,0,0))+chunk(b'IDAT',zlib.compress((b'\0'+bytes(color)*64)*32))+chunk(b'IEND',b'')
with tempfile.TemporaryDirectory() as temporary:
 videos={}
 for name,color in [('videoA','red'),('videoB','blue'),('videoC','green')]:
  path=Path(temporary)/(name+'.mp4');subprocess.run(['ffmpeg','-v','error','-f','lavfi','-i',f'color=c={color}:s=64x32:r=15:d=4','-c:v','libx264','-pix_fmt','yuv420p','-movflags','+faststart','-an',str(path)],check=True);videos[name]=path.read_bytes()
 class Handler(http.server.SimpleHTTPRequestHandler):
  def __init__(self,*args,**kwargs):super().__init__(*args,directory=str(root),**kwargs)
  def do_GET(self):
   if self.path.startswith('/design-check'):
    payload=(preview if 'preview' in self.path else ui).encode();kind='text/html; charset=utf-8'
   elif self.path.startswith('/media/'):
    name=self.path.split('/')[-1]
    if name=='slowImage':time.sleep(.65)
    payload=videos.get(name,png((255,0,0) if name=='imageA' else (0,0,255)));kind='video/mp4' if name in videos else 'image/png'
   else:return super().do_GET()
   self.send_response(200);self.send_header('Content-Type',kind);self.send_header('Content-Length',str(len(payload)));self.end_headers()
   try:self.wfile.write(payload)
   except (BrokenPipeError,ConnectionResetError):pass
  def log_message(self,*args):pass
 with socketserver.ThreadingTCPServer(('127.0.0.1',0),Handler) as server:
  threading.Thread(target=server.serve_forever,daemon=True).start()
  for role in ['manager','store','preview']:
   result=subprocess.run(['node',str(root.parent/'tests/browser-runner.mjs'),f'http://127.0.0.1:{server.server_address[1]}/design-check?{role}'],capture_output=True,text=True,timeout=45)
   assert result.returncode==0,result.stderr
   data=json.loads(result.stdout);print(role,data);assert all(data['checks'].values()),'Design/intake/preview browser check failed';assert data['viewport']['width']==390
  server.shutdown()
